package com.vynedam.stockai.service; import com.vynedam.stockai.domain.*; import com.vynedam.stockai.dto.OperationsDtos.*; import com.vynedam.stockai.exception.ApiException; import com.vynedam.stockai.model.*; import com.vynedam.stockai.repository.*; import java.time.Instant; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service;
@Service public class ProductionService{private final ProductionRunRepository runs;private final ProductRepository products;private final BatchRepository batches;private final WarehouseService warehouses;public ProductionService(ProductionRunRepository r,ProductRepository p,BatchRepository b,WarehouseService w){runs=r;products=p;batches=b;warehouses=w;}public List<ProductionRun>list(){return runs.findAll();}public ProductionRun start(ProductionRunRequest r,String actor){products.findById(r.productId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Product not found"));warehouses.assertOperationalAccess(r.warehouseId(),actor);var run=new ProductionRun();run.runNumber="RUN-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();run.productId=r.productId();run.unitId=r.unitId();run.warehouseId=r.warehouseId();run.status=ProductionRunStatus.IN_PROGRESS;run.startedBy=actor;run.startedAt=Instant.now();run.consumptions=r.consumptions().stream().map(x->{var b=batches.findById(x.batchId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Raw-material batch not found"));if(b.status!=BatchStatus.AVAILABLE||b.quantity<x.quantity())throw new ApiException(HttpStatus.CONFLICT,"INSUFFICIENT_STOCK","Raw-material batch is unavailable or insufficient");b.quantity-=x.quantity();if(b.quantity==0)b.status=BatchStatus.CONSUMED;batches.save(b);var c=new ProductionRun.Consumption();c.batchId=x.batchId();c.quantity=x.quantity();return c;}).toList();return runs.save(run);}public ProductionRun complete(String id,CompleteRunRequest r,String actor){var run=runs.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Production run not found"));if(run.status!=ProductionRunStatus.IN_PROGRESS)throw new ApiException(HttpStatus.CONFLICT,"INVALID_STATE","Run is not in progress");warehouses.assertOperationalAccess(run.warehouseId,actor);var product=products.findById(run.productId).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Product not found"));var b=new Batch();b.batchNumber=r.outputBatchNumber().toUpperCase();b.materialId=product.id;b.warehouseId=run.warehouseId;b.unitId=run.unitId;b.quantity=r.outputQuantity();b.uom=r.outputUom();b.receivedAt=Instant.now();b.status=BatchStatus.AVAILABLE;batches.save(b);run.outputQuantity=r.outputQuantity();run.outputBatchId=b.id;run.status=ProductionRunStatus.COMPLETED;run.completedBy=actor;run.completedAt=Instant.now();return runs.save(run);}}
